<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}
else if (allTasks is null)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Total</small><strong>@allTasks.Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">To Do</small><strong>@GetTasksForStatus("To Do").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">In Progress</small><strong>@GetTasksForStatus("In Progress").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Done</small><strong>@GetTasksForStatus("Done").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Overdue</small><strong class="text-danger">@allTasks.Count(t => t.DueDate.Date < DateTime.Today)</strong></div></div>
    </div>

    <!-- Search -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..." @bind="searchTerm" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @foreach (var status in Statuses)
        {
            var columnTasks = GetFilteredTasksForStatus(status);
            int statusIndex = Array.IndexOf(Statuses, status);

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@status</strong>
                        <span class="badge bg-secondary">@columnTasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2" style="min-height:200px; overflow-y:auto;">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <small class="text-muted">@task.Assignee</small>
                                    <div class="d-flex align-items-center justify-content-between mt-1">
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                        <small>@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex justify-content-between mt-2">
                                        @if (statusIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@isBusy"
                                                    @onclick="() => MoveTask(task.Id, Statuses[statusIndex - 1])">
                                                &larr; Move Left
                                            </button>
                                        }
                                        else
                                        {
                                            <span></span>
                                        }
                                        @if (statusIndex < Statuses.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@isBusy"
                                                    @onclick="() => MoveTask(task.Id, Statuses[statusIndex + 1])">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingForStatus == status)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2" @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm flex-fill" disabled="@isBusy" @onclick="SaveNewTask">Save</button>
                                        <button class="btn btn-outline-secondary btn-sm flex-fill" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                disabled="@(addingForStatus is not null)"
                                @onclick="() => StartAdd(status)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

