+                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-2" @bind="newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm flex-fill" disabled="@isBusy" @onclick="SaveNewTask">Save</button>
+                                        <button class="btn btn-outline-secondary btn-sm flex-fill" @onclick="CancelAdd">Cancel</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer">
+                        <button class="btn btn-outline-primary btn-sm w-100"
+                                disabled="@(addingForStatus is not null)"
+                                @onclick="() => StartAdd(status)">
+                            + Add Task
+                        </button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };
+
+    private List<TaskItem>? allTasks;
+    private string? errorMessage;
+    private string searchTerm = string.Empty;
+    private bool isBusy;
+
+    // Add-task form state
+    private string? addingForStatus;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private List<TaskItem> GetTasksForStatus(string status) =>
+        allTasks!.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForStatus(string status) =>
+        allTasks!
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrWhiteSpace(searchTerm)
+                        || t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        isBusy = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = allTasks!.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = allTasks[idx];
+                allTasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isBusy = false;
+        }
+    }
+
+    private void StartAdd(string status)
+    {
+        addingForStatus = status;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => addingForStatus = null;
+
+    private async Task SaveNewTask()
+    {
+        if (string.IsNullOrWhiteSpace(newTitle) || addingForStatus is null)
+            return;
+
+        isBusy = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
+            allTasks!.Add(created with { Status = addingForStatus });
+            addingForStatus = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isBusy = false;
+        }
+    }
+}
